class Solution {
  public int longestSubsequence(int[] nums) {
    int best = 0;
    int[] tails = new int[nums.length];
    for (int bit = 0; bit < 31; bit++) {
      int len = 0;
      for (int x : nums) {
        if ((x >> bit & 1) == 0) continue;
        int lo = 0, hi = len;
        while (lo < hi) {
          int mid = (lo + hi) >>> 1;
          if (tails[mid] < x) lo = mid + 1;
          else hi = mid;
        }
        tails[lo] = x;
        if (lo == len) len++;
      }
      best = Math.max(best, len);
    }
    return best;
  }
}
